40232.737,0],\\n      \\"Zone 6\\":[195329.26,207668.023,217606.716,231907.386,230027.748,220561.399,66144.655,0],\\n      \\"WS_Upper_Area1\\":[124914.07,164675.513,175507.093,138362.074,126706.954,108369.028,26332.222,0],\\n      \\"Other\\":[140944.854,147558.113,157579.653,158908.341,129049.758,129806.275,36449.145,0],\\n      \\"Zone 4\\":[110100.857,114425.54,132646.886,140115.336,103581.976,86922.05,18544.3,0]\\n    };\\n\\n    function sum(arr){ return arr.reduce((a,b)=>a+Number(b||0),0); }\\n    function formatNumber(x){\\n      if (x === null || x === undefined) return \\"-\\";\\n      const num = Number(x);\\n      if (Number.isNaN(num)) return \\"-\\";\\n      // compact-ish formatting\\n      if (Math.abs(num) >= 1e9) return (num/1e9).toFixed(2)+\\"B\\";\\n      if (Math.abs(num) >= 1e6) return (num/1e6).toFixed(2)+\\"M\\";\\n      if (Math.abs(num) >= 1e3) return (num/1e3).toFixed(2)+\\"K\\";\\n      return num.toLocaleString(undefined, {maximumFractionDigits:2});\\n    }\\n\\n    // Fill zone select\\n    const zoneSelect = document.getElementById('zoneSelect');\\n    zones.forEach((z)=>{\\n      const opt = document.createElement('option');\\n      opt.value = z;\\n      opt.textContent = z;\\n      opt.selected = (z === \\"<NULL>\\" || z === \\"Zone 1\\" || z === \\"Zone 2\\"); // default selection\\n      zoneSelect.appendChild(opt);\\n    });\\n\\n    // Build top table\\n    const rows = zones.map(z=>({\\n      zone:z,\\n      Revenue: sum(revenue[z]),\\n      PC: sum(pc[z]),\\n      UC: sum(uc[z])\\n    })).sort((a,b)=>b.Revenue-a.Revenue);\\n\\n    const topTableBody = document.getElementById('topTableBody');\\n    rows.forEach(r=>{\\n      const tr = document.createElement('tr');\\n      tr.innerHTML = `\\n        <td style=\\"text-align:left;\\"><span class=\\"mono\\">${r.zone}</span></td>\\n        <td>${formatNumber(r.Revenue)}</td>\\n        <td>${formatNumber(r.PC)}</td>\\n        <td>${formatNumber(r.UC)}</td>\\n      `;\\n      topTableBody.appendChild(tr);\\n    });\\n\\n    // Matrix head/body (Revenue)\\n    const matrixHead = document.getElementById('matrixHead');\\n    const matrixBody = document.getElementById('matrixBody');\\n    // head\\n    matrixHead.innerHTML = \\"\\";\\n    const th0 = document.createElement('th'); th0.textContent=\\"Month\\"; matrixHead.appendChild(th0);\\n    zones.forEach(z=>{\\n      const th = document.createElement('th');\\n      th.textContent = z;\\n      matrixHead.appendChild(th);\\n    });\\n    // body\\n    months.forEach((m, idx)=>{\\n      const tr = document.createElement('tr');\\n      const td0 = document.createElement('td');\\n      td0.textContent = m;\\n      tr.appendChild(td0);\\n      zones.forEach(z=>{\\n        const td = document.createElement('td');\\n        td.textContent = formatNumber(revenue[z][idx]);\\n        tr.appendChild(td);\\n      });\\n      matrixBody.appendChild(tr);\\n    });\\n\\n    const colorPool = [\\n      '#1f77b4','#ff7f0e','#2ca02c','#d62728','#9467bd',\\n      '#8c564b','#e377c2','#7f7f7f','#bcbd22','#17becf'\\n    ];\\n    function colorFor(i){ return colorPool[i % colorPool.length]; }\\n\\n    // Main interactive line chart\\n    const ctx = document.getElementById('lineChart').getContext('2d');\\n    let chartMain;\\n\\n    function getSelectedZones(){\\n      return Array.from(zoneSelect.selectedOptions).map(o=>o.value);\\n    }\\n\\n    function getMetricData(metric, z){\\n      if (metric===\\"Revenue\\") return revenue[z];\\n      if (metric===\\"PC\\") return pc[z];\\n      return uc[z];\\n    }\\n\\n    function computeTotals(metric, selectedZones){\\n      const totals = selectedZones.reduce((acc, z)=>{\\n        const arr = getMetricData(metric, z);\\n        arr.forEach((val, i)=>{});\\n        return acc;\\n      }, {});\\n    }\\n\\n    function setKpis(selectedZones){\\n      const kpiRevenue = document.getElementById('kpiRevenue');\\n      const kpiPC = document.getElementById('kpiPC');\\n      const kpiUC = document.getElementById('kpiUC');\\n\\n      const totalRevenue = selectedZones.reduce((a,z)=>a+sum(revenue[z]),0);\\n      const totalPC = selectedZones.reduce((a,z)=>a+sum(pc[z]),0);\\n      const totalUC = selectedZones.reduce((a,z)=>a+sum(uc[z]),0);\\n\\n      kpiRevenue.textContent = formatNumber(totalRevenue);\\n      kpiPC.textContent = formatNumber(totalPC);\\n      kpiUC.textContent = formatNumber(totalUC);\\n    }\\n\\n    function renderMain(){\\n      const selectedZones = getSelectedZones();\\n      const metric = document.getElementById('metricSelect').value;\\n\\n      setKpis(selectedZones);\\n\\n      if (chartMain) chartMain.destroy();\\n\\n      const datasets = selectedZones.map((z, i)=>({\\n        label: z,\\n        data: getMetricData(metric, z).map(Number),\\n        borderColor: colorFor(i),\\n        backgroundColor: colorFor(i),\\n        pointRadius: 3,\\n        tension: 0.25\\n      }));\\n\\n      chartMain = new Chart(ctx, {\\n        type: 'line',\\n        data: { labels: months, datasets },\\n        options: {\\n          responsive:true,\\n          maintainAspectRatio:false,\\n          plugins:{\\n            legend:{ position:'bottom', labels:{ boxWidth:10 } },\\n            tooltip:{ mode:'index', intersect:false }\\n          },\\n          interaction:{ mode:'index', intersect:false },\\n          scales:{\\n            y:{\\n              beginAtZero:true,\\n              ticks:{\\n                callback: (v)=> formatNumber(v)\\n              }\\n            }\\n          }\\n        }\\n      });\\n    }\\n\\n    document.getElementById('applyBtn').addEventListener('click', ()=>{\\n      renderMain();\\n    });\\n\\n    document.getElementById('metricSelect').addEventListener('change', ()=>{\\n      renderMain();\\n    });\\n\\n    // 3 small charts\\n    function renderSmallCharts(){\\n      const chartCfg = (canvasId, metric) => {\\n        const c = document.getElementById(canvasId).getContext('2d');\\n        return new Chart(c, {\\n          type:'line',\\n          data:{\\n            labels: months,\\n            datasets: zones.map((z,i)=>({\\n              label:z,\\n              data: getMetricData(metric,z).map(Number),\\n              borderColor: colorFor(i),\\n              backgroundColor: 'transparent',\\n              pointRadius: 2,\\n              tension: 0.25\\n            }))\\n          },\\n          options:{\\n            responsive:true,\\n            maintainAspectRatio:false,\\n            plugins:{\\n              legend:{ display:false },\\n              tooltip:{ mode:'index', intersect:false }\\n            },\\n            interaction:{ mode:'index', intersect:false },\\n            scales:{\\n              y:{ beginAtZero:true, ticks:{ callback:(v)=>formatNumber(v) } }\\n            }\\n          }\\n        });\\n      };\\n      renderSmallCharts._r = [\\n        chartCfg('chartRevenue','Revenue'),\\n        chartCfg('chartPC','PC'),\\n        chartCfg('chartUC','UC')\\n      ];\\n    }\\n\\n    document.getElementById('updatedAt').textContent = new Date().toLocaleString();\\n\\n    // initial render\\n    renderMain();\\n    renderSmallCharts();\\n  </script>\\n</body>\\n</html>\\n```\\n\\n\\n\\u0e16\\u0e49\\u0e32\\u0e15\\u0e49\\u0e2d\\u0e07\\u0e01\\u0e32\\u0e23\\u0e43\\u0e2b\\u0e49 dashboard \\u201c\\u0e2a\\u0e25\\u0e31\\u0e1a\\u0e44\\u0e14\\u0e49\\u0e23\\u0e30\\u0e2b\\u0e27\\u0e48\\u0e32\\u0e07 Zone \\u0e01\\u0e31\\u0e1a SubOrg\\u201d \\u0e2b\\u0e23\\u0e37\\u0e2d \\u201cTop N \\u0e01\\u0e33\\u0e2b\\u0e19\\u0e14\\u0e44\\u0e14\\u0e49 (\\u0e40\\u0e0a\\u0e48\\u0e19 Top 5/Top 20)\\u201d \\u0e1a\\u0e2d\\u0e01\\u0e1c\\u0e21\\u0e44\\u0e14\\u0e49\\u0e40\\u0e25\\u0e22\\u0e04\\u0e23\\u0e31\\u0e1a \\u0e40\\u0e14\\u0e35\\u0e4b\\u0e22\\u0e27\\u0e1c\\u0e21\\u0e1b\\u0e23\\u0e31\\u0e1a\\u0e42\\u0e04\\u0e23\\u0e07 dashboard \\u0e43\\u0e2b\\u0e49\\u0e15\\u0e23\\u0e07\\u0e01\\u0e31\\u0e1a\\u0e01\\u0e32\\u0e23\\u0e43\\u0e0a\\u0e49\\u0e07\\u0e32\\u0e19\\u0e08\\u0e23\\u0e34\\u0e07\\u0e02\\u0e2d\\u0e07\\u0e04\\u0e38\\u0e13"	[{"type": "message", "id": "msg_8d4a7b51313141478324ec74", "status": "completed", "role": "assistant", "content": [{"type": "output_text", "text": "\\u0e44\\u0e14\\u0e49\\u0e04\\u0e23\\u0e31\\u0e1a \\u0e1c\\u0e21\\u0e17\\u0e33\\u0e40\\u0e1b\\u0e47\\u0e19 **Dashboard (single HTML file)** \\u0e41\\u0e2a\\u0e14\\u0e07\\n- KPI \\u0e23\\u0e27\\u0e21 Revenue / PC / UC (\\u0e0a\\u0e48\\u0e27\\u0e07 2025/01-2025/08)\\n- \\u0e15\\u0e32\\u0e23\\u0e32\\u0e07 Top10 Zone (\\u0e15\\u0e32\\u0e21 Revenue \\u0e23\\u0e27\\u0e21\\u0e17\\u0e31\\u0e49\\u0e07\\u0e0a\\u0e48\\u0e27\\u0e07) \\u0e1e\\u0e23\\u0e49\\u0e2d\\u0e21\\u0e04\\u0e48\\u0e32 Revenue/PC/UC\\n- 3 \\u0e01\\u0e23\\u0e32\\u0e1f\\u0e41\\u0e19\\u0e27\\u0e42\\u0e19\\u0e49\\u0e21\\u0e23\\u0e32\\u0e22\\u0e40\\u0e14\\u0e37\\u0e2d\\u0e19 (Revenue/PC/UC) \\u0e41\\u0e22\\u0e01\\u0e15\\u0e32\\u0e21 Zone (Top10)\\n- \\u0e04\\u0e48\\u0e32\\u0e43\\u0e19\\u0e15\\u0e32\\u0e23\\u0e32\\u0e07 \\u201cMatrix\\u201d \\u0e41\\u0e16\\u0e27=\\u0e40\\u0e14\\u0e37\\u0e2d\\u0e19 (\\u0e41\\u0e2a\\u0e14\\u0e07 Revenue)\\n\\n> \\u0e2b\\u0e21\\u0e32\\u0e22\\u0e40\\u0e2b\\u0e15\\u0e38: \\u0e21\\u0e35\\u0e04\\u0e48\\u0e32 **Zone = NULL** \\u0e15\\u0e34\\u0e14 Top10 \\u0e08\\u0e36\\u0e07\\u0e16\\u0e39\\u0e01\\u0e19\\u0e33\\u0e21\\u0e32\\u0e41\\u0e2a\\u0e14\\u0e07\\u0e40\\u0e1b\\u0e47\\u0e19 `<NULL>` \\u0e15\\u0e32\\u0e21\\u0e02\\u0e49\\u0e2d\\u0e21\\u0e39\\u0e25\\u0e17\\u0e35\\u0e48\\u0e14\\u0e36\\u0e07\\u0e44\\u0e14\\u0e49\\u0e08\\u0e23\\u0e34\\u0e07\\n\\n```html\\n<!doctype html>\\n<html lang=\\"th\\">\\n<head>\\n  <meta charset=\\"utf-8\\"/>\\n  <meta name=\\"viewport\\" content=\\"width=device-width, initial-scale=1\\"/>\\n  <title>Sales Performance Dashboard - Zone (2025/01-2025/08)</title>\\n  <style>\\n    body{font-family: system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif; margin:14px; color:#111;}\\n    .grid{display:grid; grid-template-columns: 1.1fr 0.9fr; gap:12px;}\\n    @media (max-width: 980px){ .grid{grid-template-columns:1fr;} }\\n    .card{background:#fff; border:1px solid #e6e6e6; border-radius:12px; padding:12px;}\\n    .kpis{display:grid; grid-template-columns: repeat(3, 1fr); gap:10px;}\\n    @media (max-width: 720px){ .kpis{grid-template-columns:1fr; } }\\n    .kpi{padding:10px; border-radius:10px; border:1px solid #eee; }\\n    .kpi .label{font-size:12px; color:#666;}\\n    .kpi .value{font-size:20px; font-weight:700; margin-top:4px;}\\n    .row{display:flex; gap:12px; flex-wrap:wrap;}\\n    .chartWrap{height:320px;}\\n    canvas{max-width:100%;}\\n    table{width:100%; border-collapse:collapse; font-size:12px;}\\n    th,td{border-bottom:1px solid #eee; padding:8px 6px; text-align:right; white-space:nowrap;}\\n    th:first-child, td:first-child{text-align:left;}\\n    th{background:#fafafa; position:sticky; top:0; z-index:1;}\\n    .badge{display:inline-block; padding:2px 8px; border:1px solid #ddd; border-radius:999px; font-size:12px; background:#fff;}\\n    .muted{color:#666;}\\n    select, button{padding:8px 10px; border-radius:10px; border:1px solid #ddd; background:#fff;}\\n    .controls{display:flex; gap:10px; flex-wrap:wrap; align-items:center; justify-content:space-between; margin-bottom:8px;}\\n    .controls-left{display:flex; gap:10px; flex-wrap:wrap; align-items:center;}\\n    .small{font-size:12px;}\\n    .mono{font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;}\\n    .empty{padding:14px; border:1px dashed #ccc; border-radius:12px; color:#666;}\\n  </style>\\n</head>\\n\\n<body>\\n  <div class=\\"card\\">\\n    <div class=\\"row\\" style=\\"justify-content:space-between; align-items:flex-start;\\">\\n      <div>\\n        <div style=\\"font-size:18px; font-weight:800;\\">Haadthip - Sales Performance Dashboard</div>\\n        <div class=\\"muted small\\">\\u0e0a\\u0e48\\u0e27\\u0e07\\u0e40\\u0e27\\u0e25\\u0e32: <span class=\\"mono\\">2025/01 - 2025/08</span> | \\u0e41\\u0e01\\u0e19: Zone (Top10 \\u0e15\\u0e32\\u0e21 Revenue) | Source: <span class=\\"mono\\">dv.mlv_sale_preformance_aggregate</span></div>\\n        <div style=\\"margin-top:8px;\\">\\n          <span class=\\"badge\\">Revenue</span>\\n          <span class=\\"badge\\">PC</span>\\n          <span class=\\"badge\\">UC</span>\\n          <span class=\\"badge\\">Zone=<span class=\\"mono\\">&lt;NULL&gt;</span> \\u0e23\\u0e27\\u0e21\\u0e2d\\u0e22\\u0e39\\u0e48\\u0e43\\u0e19 Top10</span>\\n        </div>\\n      </div>\\n      <div class=\\"muted small\\" style=\\"text-align:right;\\">\\n        <div>Updated: <span id=\\"updatedAt\\" class=\\"mono\\">-</span></div>\\n      </div>\\n    </div>\\n  </div>\\n\\n  <div style=\\"height:12px;\\"></div>\\n\\n  <div class=\\"grid\\">\\n    <div class=\\"card\\">\\n      <div class=\\"controls\\">\\n        <div class=\\"controls-left\\">\\n          <div>\\n            <div class=\\"small muted\\">\\u0e15\\u0e31\\u0e27\\u0e40\\u0e25\\u0e37\\u0e2d\\u0e01\\u0e41\\u0e2a\\u0e14\\u0e07\\u0e40\\u0e2a\\u0e49\\u0e19 (\\u0e40\\u0e25\\u0e37\\u0e2d\\u0e01\\u0e44\\u0e14\\u0e49\\u0e2b\\u0e25\\u0e32\\u0e22\\u0e04\\u0e48\\u0e32)</div>\\n            <select id=\\"zoneSelect\\" multiple size=\\"6\\" style=\\"min-width:260px;\\">\\n              <!-- filled by JS -->\\n            </select>\\n          </div>\\n          <div>\\n            <div class=\\"small muted\\">\\u0e2a\\u0e23\\u0e38\\u0e1b\\u0e40\\u0e1b\\u0e47\\u0e19</div>\\n            <select id=\\"metricSelect\\" style=\\"min-width:220px;\\">\\n              <option value=\\"Revenue\\" selected>Revenue (SumBillNetRevenue)</option>\\n              <option value=\\"PC\\">PC (SumBillPCVolume)</option>\\n              <option value=\\"UC\\">UC (SumBillUCVolume)</option>\\n            </select>\\n            <div style=\\"margin-top:8px;\\">\\n              <button id=\\"applyBtn\\" type=\\"button\\">Apply</button>\\n            </div>\\n          </div>\\n        </div>\\n      </div>\\n\\n      <div class=\\"kpis\\">\\n        <div class=\\"kpi\\">\\n          <div class=\\"label\\">Total Revenue (\\u0e0a\\u0e48\\u0e27\\u0e07\\u0e17\\u0e35\\u0e48\\u0e01\\u0e23\\u0e2d\\u0e07)</div>\\n          <div class=\\"value\\" id=\\"kpiRevenue\\">-</div>\\n        </div>\\n        <div class=\\"kpi\\">\\n          <div class=\\"label\\">Total PC (\\u0e0a\\u0e48\\u0e27\\u0e07\\u0e17\\u0e35\\u0e48\\u0e01\\u0e23\\u0e2d\\u0e07)</div>\\n          <div class=\\"value\\" id=\\"kpiPC\\">-</div>\\n        </div>\\n        <div class=\\"kpi\\">\\n          <div class=\\"label\\">Total UC (\\u0e0a\\u0e48\\u0e27\\u0e07\\u0e17\\u0e35\\u0e48\\u0e01\\u0e23\\u0e2d\\u0e07)</div>\\n          <div class=\\"value\\" id=\\"kpiUC\\">-</div>\\n        </div>\\n      </div>\\n\\n      <div style=\\"height:10px;\\"></div>\\n\\n      <div class=\\"chartWrap\\">\\n        <canvas id=\\"lineChart\\"></canvas>\\n      </div>\\n\\n      <div style=\\"height:10px;\\"></div>\\n\\n      <div class=\\"muted small\\">\\u0e2b\\u0e21\\u0e32\\u0e22\\u0e40\\u0e2b\\u0e15\\u0e38: \\u0e15\\u0e31\\u0e27\\u0e40\\u0e25\\u0e02\\u0e17\\u0e31\\u0e49\\u0e07\\u0e2b\\u0e21\\u0e14\\u0e40\\u0e1b\\u0e47\\u0e19\\u0e1c\\u0e25\\u0e23\\u0e27\\u0e21\\u0e08\\u0e32\\u0e01\\u0e02\\u0e49\\u0e2d\\u0e21\\u0e39\\u0e25\\u0e17\\u0e35\\u0e48\\u0e14\\u0e36\\u0e07\\u0e44\\u0e14\\u0e49\\u0e08\\u0e23\\u0e34\\u0e07\\u0e43\\u0e19\\u0e0a\\u0e48\\u0e27\\u0e07\\u0e40\\u0e27\\u0e25\\u0e32\\u0e14\\u0e31\\u0e07\\u0e01\\u0e25\\u0e48\\u0e32\\u0e27</div>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <div style=\\"display:flex; justify-content:space-between; align-items:center; gap:10px; margin-bottom:8px;\\">\\n        <div>\\n          <div style=\\"font-weight:800;\\">Top10 Zones (\\u0e15\\u0e32\\u0e21 Revenue \\u0e23\\u0e27\\u0e21\\u0e17\\u0e31\\u0e49\\u0e07\\u0e0a\\u0e48\\u0e27\\u0e07)</div>\\n          <div class=\\"muted small\\">\\u0e41\\u0e2a\\u0e14\\u0e07 Revenue / PC / UC \\u0e23\\u0e27\\u0e21\\u0e0a\\u0e48\\u0e27\\u0e07 2025/01-2025/08</div>\\n        </div>\\n      </div>\\n\\n      <div style=\\"max-height:260px; overflow:auto; border-radius:10px; border:1px solid #eee;\\">\\n        <table>\\n          <thead>\\n            <tr>\\n              <th>Zone</th>\\n              <th>Revenue</th>\\n              <th>PC</th>\\n              <th>UC</th>\\n            </tr>\\n          </thead>\\n          <tbody id=\\"topTableBody\\"></tbody>\\n        </table>\\n      </div>\\n\\n      <div style=\\"height:12px;\\"></div>\\n\\n      <div style=\\"font-weight:800;\\">Matrix: Revenue \\u0e23\\u0e32\\u0e22\\u0e40\\u0e14\\u0e37\\u0e2d\\u0e19 x Zone</div>\\n      <div class=\\"muted small\\" style=\\"margin-top:4px;\\">(\\u0e41\\u0e2a\\u0e14\\u0e07\\u0e40\\u0e09\\u0e1e\\u0e32\\u0e30 Zone Top10)</div>\\n\\n      <div style=\\"max-height:220px; overflow:auto; border-radius:10px; border:1px solid #eee; margin-top:8px;\\">\\n        <table>\\n          <thead>\\n            <tr id=\\"matrixHead\\"></tr>\\n          </thead>\\n          <tbody id=\\"matrixBody\\"></tbody>\\n        </table>\\n      </div>\\n\\n      <div style=\\"height:8px;\\"></div>\\n      <div class=\\"muted small\\">Source/Filters: BillingDate >= 2025-01-01 \\u0e41\\u0e25\\u0e30 < 2025-09-01</div>\\n    </div>\\n  </div>\\n\\n  <div style=\\"height:12px;\\"></div>\\n\\n  <div class=\\"card\\">\\n    <div style=\\"font-weight:800; margin-bottom:6px;\\">\\u0e41\\u0e19\\u0e27\\u0e42\\u0e19\\u0e49\\u0e21\\u0e23\\u0e32\\u0e22\\u0e40\\u0e14\\u0e37\\u0e2d\\u0e19 (Top10 Zone) - Revenue/PC/UC</div>\\n    <div class=\\"muted small\\" style=\\"margin-bottom:10px;\\">3 \\u0e01\\u0e23\\u0e32\\u0e1f (\\u0e2a\\u0e25\\u0e31\\u0e1a metric \\u0e43\\u0e19\\u0e01\\u0e23\\u0e32\\u0e1f\\u0e2b\\u0e25\\u0e31\\u0e01\\u0e44\\u0e14\\u0e49) \\u0e41\\u0e15\\u0e48\\u0e14\\u0e49\\u0e32\\u0e19\\u0e25\\u0e48\\u0e32\\u0e07\\u0e19\\u0e35\\u0e49\\u0e41\\u0e2a\\u0e14\\u0e07\\u0e04\\u0e23\\u0e1a\\u0e17\\u0e31\\u0e49\\u0e07 3 \\u0e40\\u0e1e\\u0e37\\u0e48\\u0e2d\\u0e40\\u0e17\\u0e35\\u0e22\\u0e1a\\u0e20\\u0e32\\u0e1e\\u0e23\\u0e27\\u0e21</div>\\n    <div class=\\"row\\">\\n      <div class=\\"card\\" style=\\"flex:1; min-width:320px; height:360px;\\">\\n        <div class=\\"small muted\\" style=\\"margin-bottom:6px;\\">Revenue</div>\\n        <canvas id=\\"chartRevenue\\"></canvas>\\n      </div>\\n      <div class=\\"card\\" style=\\"flex:1; min-width:320px; height:360px;\\">\\n        <div class=\\"small muted\\" style=\\"margin-bottom:6px;\\">PC</div>\\n        <canvas id=\\"chartPC\\"></canvas>\\n      </div>\\n      <div class=\\"card\\" style=\\"flex:1; min-width:320px; height:360px;\\">\\n        <div class=\\"small muted\\" style=\\"margin-bottom:6px;\\">UC</div>\\n        <canvas id=\\"chartUC\\"></canvas>\\n      </div>\\n    </div>\\n  </div>\\n\\n  <!-- Chart.js -->\\n  <script src=\\"https://cdn.jsdelivr.net/npm/chart.js@4.4.3/dist/chart.umd.min.js\\"></script>\\n  <script>\\n    const months = [\\"2025-01\\",\\"2025-02\\",\\"2025-03\\",\\"2025-04\\",\\"2025-05\\",\\"2025-06\\",\\"2025-07\\",\\"2025-08\\"];\\n\\n    // Top10 Zones (\\u0e08\\u0e32\\u0e01\\u0e1c\\u0e25\\u0e17\\u0e35\\u0e48\\u0e14\\u0e36\\u0e07\\u0e44\\u0e14\\u0e49)\\n    const zones = [\\"<NULL>\\",\\"Zone 1\\",\\"Zone 2\\",\\"Zone 5\\",\\"Zone 3\\",\\"Zone 7\\",\\"Zone 6\\",\\"WS_Upper_Area1\\",\\"Other\\",\\"Zone 4\\"];\\n\\n    // Data (Revenue matrix)\\n    const revenue = {\\n      \\"<NULL>\\":[365638322.27,428984447.17,493489921.94,443027429.07,389361645.82,354696564.65,105936778.34,560.70],\\n      \\"Zone 1\\":[42011226.42,50811338.49,55437149.62,54681107.54,49980308.95,48144042.13,12750876.31,0],\\n      \\"Zone 2\\":[46873342.02,45880567.73,44904759.23,45619505.29,30787665.36,29745423.36,7302546.29,0],\\n      \\"Zone 5\\":[26292952.34,28506472.99,30892055.53,33196048.21,24941444.26,22887300.33,5681701.53,0],\\n      \\"Zone 3\\":[20291099.34,23906628.32,27737861.71,32242667.76,27248415.73,23897982.85,5837046.81,0],\\n      \\"Zone 7\\":[20427087.39,22132516.39,24491651.94,26630210.90,24911759.37,21776126.82,4711103.87,0],\\n      \\"Zone 6\\":[18316358.58,20029219.14,20968219.19,22545111.78,22194538.19,20031649.11,5911929.64,0],\\n      \\"WS_Upper_Area1\\":[15854462.72,21233405.68,22204930.33,17756667.45,15867738.85,13332874.06,3263004.25,0],\\n      \\"Other\\":[16292260.48,17438156.38,18137892.54,18404383.15,13870740.05,13943543.32,4096582.75,0],\\n      \\"Zone 4\\":[13397243.24,14347993.85,16283334.95,17135317.03,12263564.05,9994880.36,2097837.73,0]\\n    };\\n\\n    // PC matrix\\n    const pc = {\\n      \\"<NULL>\\":[1804489.38,2032287.058,2498999.472,2226196.709,2003912.099,1789391.897,587842.254,10.0],\\n      \\"Zone 1\\":[229719,273662,304792.75,300394,281060,279413,74877,0],\\n      \\"Zone 2\\":[297453,286035,286307.375,286054,203661,202935,49942,0],\\n      \\"Zone 5\\":[157766,171327.25,183485,197198,156138,149565.75,36553,0],\\n      \\"Zone 3\\":[121683,142321.5,164088,188577,164639.875,149883.75,36184,0],\\n      \\"Zone 7\\":[122264,129763,137253,155242,156424,139732,30738,0],\\n      \\"Zone 6\\":[141810,152527,159130,167521.75,171330,163997,49167,0],\\n      \\"WS_Upper_Area1\\":[72169,99218,104306,83151,75214,64648,15527,0],\\n      \\"Other\\":[103266,106873,112684,112996,90770,92434,27085,0],\\n      \\"Zone 4\\":[76117,83541.25,94754,99923,74882,62983,13995,0]\\n    };\\n\\n    // UC matrix\\n    const uc = {\\n      \\"<NULL>\\":[3055736.061,3596977.907,4389370.462,3990272.747,3378200.768,3014124.372,911457.751,11.62],\\n      \\"Zone 1\\":[369444.78,440383.051,481637.486,475855.815,441336.068,430589.232,112420.004,0],\\n      \\"Zone 2\\":[369505.561,357092.436,365073.02,363847.558,263412.912,263472.138,62915.495,0],\\n      \\"Zone 5\\":[217922.566,235947.146,254731.969,276366.52,211926.463,201003.797,49324.905,0],\\n      \\"Zone 3\\":[172043.162,199331.391,234397.559,270326.493,229976.789,209215.459,50145.53,0],\\n      \\"Zone 7\\":[167544.184,183907.729,200012.227,215620.321,199600.614,178938.456,40232.737,0],\\n      \\"Zone 6\\":[195329.26,207668.023,217606.716,231907.386,230027.748,220561.399,66144.655,0],\\n      \\"WS_Upper_Area1\\":[124914.07,164675.513,175507.093,138362.074,126706.954,108369.028,26332.222,0],\\n      \\"Other\\":[140944.854,147558.113,157579.653,158908.341,129049.758,129806.275,36449.145,0],\\n      \\"Zone 4\\":[110100.857,114425.54,132646.886,140115.336,103581.976,86922.05,18544.3,0]\\n    };\\n\\n    function sum(arr){ return arr.reduce((a,b)=>a+Number(b||0),0); }\\n    function formatNumber(x){\\n      if (x === null || x === undefined) return \\"-\\";\\n      const num = Number(x);\\n      if (Number.isNaN(num)) return \\"-\\";\\n      // compact-ish formatting\\n      if (Math.abs(num) >= 1e9) return (num/1e9).toFixed(2)+\\"B\\";\\n      if (Math.abs(num) >= 1e6) return (num/1e6).toFixed(2)+\\"M\\";\\n      if (Math.abs(num) >= 1e3) return (num/1e3).toFixed(2)+\\"K\\";\\n      return num.toLocaleString(undefined, {maximumFractionDigits:2});\\n    }\\n\\n    // Fill zone select\\n    const zoneSelect = document.getElementById('zoneSelect');\\n    zones.forEach((z)=>{\\n      const opt = document.createElement('option');\\n      opt.value = z;\\n      opt.textContent = z;\\n      opt.selected = (z === \\"<NULL>\\" || z === \\"Zone 1\\" || z === \\"Zone 2\\"); // default selection\\n      zoneSelect.appendChild(opt);\\n    });\\n\\n    // Build top table\\n    const rows = zones.map(z=>({\\n      zone:z,\\n      Revenue: sum(revenue[z]),\\n      PC: sum(pc[z]),\\n      UC: sum(uc[z])\\n    })).sort((a,b)=>b.Revenue-a.Revenue);\\n\\n    const topTableBody = document.getElementById('topTableBody');\\n    rows.forEach(r=>{\\n      const tr = document.createElement('tr');\\n      tr.innerHTML = `\\n        <td style=\\"text-align:left;\\"><span class=\\"mono\\">${r.zone}</span></td>\\n        <td>${formatNumber(r.Revenue)}</td>\\n        <td>${formatNumber(r.PC)}</td>\\n        <td>${formatNumber(r.UC)}</td>\\n      `;\\n      topTableBody.appendChild(tr);\\n    });\\n\\n    // Matrix head/body (Revenue)\\n    const matrixHead = document.getElementById('matrixHead');\\n    const matrixBody = document.getElementById('matrixBody');\\n    // head\\n    matrixHead.innerHTML = \\"\\";\\n    const th0 = document.createElement('th'); th0.textContent=\\"Month\\"; matrixHead.appendChild(th0);\\n    zones.forEach(z=>{\\n      const th = document.createElement('th');\\n      th.textContent = z;\\n      matrixHead.appendChild(th);\\n    });\\n    // body\\n    months.forEach((m, idx)=>{\\n      const tr = document.createElement('tr');\\n      const td0 = document.createElement('td');\\n      td0.textContent = m;\\n      tr.appendChild(td0);\\n      zones.forEach(z=>{\\n        const td = document.createElement('td');\\n        td.textContent = formatNumber(revenue[z][idx]);\\n        tr.appendChild(td);\\n      });\\n      matrixBody.appendChild(tr);\\n    });\\n\\n    const colorPool = [\\n      '#1f77b4','#ff7f0e','#2ca02c','#d62728','#9467bd',\\n      '#8c564b','#e377c2','#7f7f7f','#bcbd22','#17becf'\\n    ];\\n    function colorFor(i){ return colorPool[i % colorPool.length]; }\\n\\n    // Main interactive line chart\\n    const ctx = document.getElementById('lineChart').getContext('2d');\\n    let chartMain;\\n\\n    function getSelectedZones(){\\n      return Array.from(zoneSelect.selectedOptions).map(o=>o.value);\\n    }\\n\\n    function getMetricData(metric, z){\\n      if (metric===\\"Revenue\\") return revenue[z];\\n      if (metric===\\"PC\\") return pc[z];\\n      return uc[z];\\n    }\\n\\n    function computeTotals(metric, selectedZones){\\n      const totals = selectedZones.reduce((acc, z)=>{\\n        const arr = getMetricData(metric, z);\\n        arr.forEach((val, i)=>{});\\n        return acc;\\n      }, {});\\n    }\\n\\n    function setKpis(selectedZones){\\n      const kpiRevenue = document.getElementById('kpiRevenue');\\n      const kpiPC = document.getElementById('kpiPC');\\n      const kpiUC = document.getElementById('kpiUC');\\n\\n      const totalRevenue = selectedZones.reduce((a,z)=>a+sum(revenue[z]),0);\\n      const totalPC = selectedZones.reduce((a,z)=>a+sum(pc[z]),0);\\n      const totalUC = selectedZones.reduce((a,z)=>a+sum(uc[z]),0);\\n\\n      kpiRevenue.textContent = formatNumber(totalRevenue);\\n      kpiPC.textContent = formatNumber(totalPC);\\n      kpiUC.textContent = formatNumber(totalUC);\\n    }\\n\\n    function renderMain(){\\n      const selectedZones = getSelectedZones();\\n      const metric = document.getElementById('metricSelect').value;\\n\\n      setKpis(selectedZones);\\n\\n      if (chartMain) chartMain.destroy();\\n\\n      const datasets = selectedZones.map((z, i)=>({\\n        label: z,\\n        data: getMetricData(metric, z).map(Number),\\n        borderColor: colorFor(i),\\n        backgroundColor: colorFor(i),\\n        pointRadius: 3,\\n        tension: 0.25\\n      }));\\n\\n      chartMain = new Chart(ctx, {\\n        type: 'line',\\n        data: { labels: months, datasets },\\n        options: {\\n          responsive:true,\\n          maintainAspectRatio:false,\\n          plugins:{\\n            legend:{ position:'bottom', labels:{ boxWidth:10 } },\\n            tooltip:{ mode:'index', intersect:false }\\n          },\\n          interaction:{ mode:'index', intersect:false },\\n          scales:{\\n            y:{\\n              beginAtZero:true,\\n              ticks:{\\n                callback: (v)=> formatNumber(v)\\n              }\\n            }\\n          }\\n        }\\n      });\\n    }\\n\\n    document.getElementById('applyBtn').addEventListener('click', ()=>{\\n      renderMain();\\n    });\\n\\n    document.getElementById('metricSelect').addEventListener('change', ()=>{\\n      renderMain();\\n    });\\n\\n    // 3 small charts\\n    function renderSmallCharts(){\\n      const chartCfg = (canvasId, metric) => {\\n        const c = document.getElementById(canvasId).getContext('2d');\\n        return new Chart(c, {\\n          type:'line',\\n          data:{\\n            labels: months,\\n            datasets: zones.map((z,i)=>({\\n              label:z,\\n              data: getMetricData(metric,z).map(Number),\\n              borderColor: colorFor(i),\\n              backgroundColor: 'transparent',\\n              pointRadius: 2,\\n              tension: 0.25\\n            }))\\n          },\\n          options:{\\n            responsive:true,\\n            maintainAspectRatio:false,\\n            plugins:{\\n              legend:{ display:false },\\n              tooltip:{ mode:'index', intersect:false }\\n            },\\n            interaction:{ mode:'index', intersect:false },\\n            scales:{\\n              y:{ beginAtZero:true, ticks:{ callback:(v)=>formatNumber(v) } }\\n            }\\n          }\\n        });\\n      };\\n      renderSmallCharts._r = [\\n        chartCfg('chartRevenue','Revenue'),\\n        chartCfg('chartPC','PC'),\\n        chartCfg('chartUC','UC')\\n      ];\\n    }\\n\\n    document.getElementById('updatedAt').textContent = new Date().toLocaleString();\\n\\n    // initial render\\n    renderMain();\\n    renderSmallCharts();\\n  </script>\\n</body>\\n</html>\\n```\\n\\n\\n\\u0e16\\u0e49\\u0e32\\u0e15\\u0e49\\u0e2d\\u0e07\\u0e01\\u0e32\\u0e23\\u0e43\\u0e2b\\u0e49 dashboard \\u201c\\u0e2a\\u0e25\\u0e31\\u0e1a\\u0e44\\u0e14\\u0e49\\u0e23\\u0e30\\u0e2b\\u0e27\\u0e48\\u0e32\\u0e07 Zone \\u0e01\\u0e31\\u0e1a SubOrg\\u201d \\u0e2b\\u0e23\\u0e37\\u0e2d \\u201cTop N \\u0e01\\u0e33\\u0e2b\\u0e19\\u0e14\\u0e44\\u0e14\\u0e49 (\\u0e40\\u0e0a\\u0e48\\u0e19 Top 5/Top 20)\\u201d \\u0e1a\\u0e2d\\u0e01\\u0e1c\\u0e21\\u0e44\\u0e14\\u0e49\\u0e40\\u0e25\\u0e22\\u0e04\\u0e23\\u0e31\\u0e1a \\u0e40\\u0e14\\u0e35\\u0e4b\\u0e22\\u0e27\\u0e1c\\u0e21\\u0e1b\\u0e23\\u0e31\\u0e1a\\u0e42\\u0e04\\u0e23\\u0e07 dashboard \\u0e43\\u0e2b\\u0e49\\u0e15\\u0e23\\u0e07\\u0e01\\u0e31\\u0e1a\\u0e01\\u0e32\\u0e23\\u0e43\\u0e