COPY public.tool (id, user_id, name, content, specs, meta, valves, updated_at, created_at) FROM stdin;
excel_reader_owui_files	490b4365-9153-406f-bd74-d898a971e18e	Excel Pandas Tool	"""\ntitle: Excel Calc\nauthor: Haadthip DIO\nversion: 1.0\nrequired_open_webui_version: 0.5.0\n\nLets the model compute over an uploaded spreadsheet instead of reading it as text.\n\nPairs with SKIP_EMBEDDING_EXTENSIONS (app/patches/skip_embedding.py): xlsx/xls/csv\nattachments never reach the vector store, so this tool is the only way the model\nsees their numbers. Bytes are read straight off Storage and parsed with pandas —\nrow counts and aggregates stay exact and don't burn context.\n\nAuthorization: a file is readable only if it is attached to the current chat\n(__files__) or owned by the calling user.\n"""\n\nimport io\nimport json\nfrom typing import Optional\n\nimport pandas as pd\nfrom pydantic import BaseModel, Field\n\nSPREADSHEET_EXTS = (".xlsx", ".xlsm", ".xls", ".csv")\nOPS = ("sum", "mean", "median", "min", "max", "count", "nunique", "std")\nNUMERIC_OPS = ("sum", "mean", "median", "std")\n\n\nclass Tools:\n    class Valves(BaseModel):\n        max_rows: int = Field(\n            default=200,\n            description="Hard cap on rows returned by read_sheet in one call",\n        )\n        max_groups: int = Field(\n            default=200,\n            description="Hard cap on groups returned by aggregate",\n        )\n\n    def __init__(self):\n        self.valves = self.Valves()\n        self._cache: tuple[str, str, bytes] | None = None\n\n    # ── file access ─────────────────────────────────────────────────────────\n\n    async def _bytes(\n        self, file_id: str, files: Optional[list[dict]], user: Optional[dict]\n    ) -> tuple[str, bytes]:\n        if self._cache and self._cache[0] == file_id:\n            return self._cache[1], self._cache[2]\n\n        from open_webui.models.files import Files\n        from open_webui.storage.provider import Storage\n\n        file = await Files.get_file_by_id(file_id)\n        if not file:\n            raise ValueError(f"file not found: {file_id}")\n\n        attached = {\n            item.get("id")\n            for item in (files or [])\n            if isinstance(item, dict) and item.get("type", "file") == "file"\n        }\n        user_id = (user or {}).get("id")\n        if file_id not in attached and file.user_id != user_id:\n            raise PermissionError(f"no access to file: {file_id}")\n\n        with open(Storage.get_file(file.path), "rb") as fh:\n            blob = fh.read()\n\n        self._cache = (file_id, file.filename, blob)\n        return file.filename, blob\n\n    @staticmethod\n    def _sheet_names(filename: str, blob: bytes) -> list[str]:\n        if filename.lower().endswith(".csv"):\n            return ["csv"]\n        return pd.ExcelFile(io.BytesIO(blob)).sheet_names\n\n    @staticmethod\n    def _frame(\n        filename: str, blob: bytes, sheet: Optional[str], header_row: int\n    ) -> pd.DataFrame:\n        if filename.lower().endswith(".csv"):\n            df = pd.read_csv(io.BytesIO(blob), header=header_row)\n        else:\n            xls = pd.ExcelFile(io.BytesIO(blob))\n            name = sheet if sheet in xls.sheet_names else xls.sheet_names[0]\n            df = xls.parse(name, header=header_row)\n        df.columns = [str(c).strip() for c in df.columns]\n        return df\n\n    async def _prepared(\n        self,\n        file_id: str,\n        sheet: Optional[str],\n        query: Optional[str],\n        header_row: int,\n        files: Optional[list[dict]],\n        user: Optional[dict],\n    ) -> tuple[str, pd.DataFrame]:\n        filename, blob = await self._bytes(file_id, files, user)\n        df = self._frame(filename, blob, sheet, header_row)\n        if query:\n            df = df.query(query)\n        return filename, df\n\n    # ── tools ───────────────────────────────────────────────────────────────\n\n    async def list_spreadsheets(\n        self,\n        __files__: Optional[list[dict]] = None,\n        __user__: Optional[dict] = None,\n    ) -> str:\n        """\n        List the spreadsheets attached to this chat, with their sheet names, column\n        names and row counts. Call this first to learn the file_id and the exact\n        column spelling needed by read_sheet and aggregate.\n\n        :return: JSON array of files, each with id, filename and sheets\n        """\n        out = []\n        for item in __files__ or []:\n            if not isinstance(item, dict) or item.get("type", "file") != "file":\n                continue\n            file_id = item.get("id")\n            name = item.get("name") or item.get("filename") or ""\n            if not file_id or not str(name).lower().endswith(SPREADSHEET_EXTS):\n                continue\n            try:\n                filename, blob = await self._bytes(file_id, __files__, __user__)\n                sheets = []\n                for sn in self._sheet_names(filename, blob):\n                    df = self._frame(filename, blob, sn, 0)\n                    sheets.append(\n                        {"sheet": sn, "rows": int(len(df)), "columns": list(df.columns)}\n                    )\n                out.append({"id": file_id, "filename": filename, "sheets": sheets})\n            except Exception as e:\n                out.append({"id": file_id, "filename": str(name), "error": str(e)})\n\n        if not out:\n            return json.dumps(\n                {\n                    "files": [],\n                    "hint": "No spreadsheet attached. Ask the user to upload .xlsx or .csv.",\n                },\n                ensure_ascii=False,\n            )\n        return json.dumps({"files": out}, ensure_ascii=False)\n\n    async def read_sheet(\n        self,\n        file_id: str,\n        sheet: Optional[str] = None,\n        columns: Optional[str] = None,\n        query: Optional[str] = None,\n        limit: int = 50,\n        offset: int = 0,\n        header_row: int = 0,\n        __files__: Optional[list[dict]] = None,\n        __user__: Optional[dict] = None,\n    ) -> str:\n        """\n        Read rows from a spreadsheet as records. Use it to inspect data, not to pull\n        the whole file — filter with query and narrow with columns instead.\n\n        :param file_id: File id from list_spreadsheets\n        :param sheet: Sheet name. Defaults to the first sheet\n        :param columns: Comma-separated column names to return. Defaults to all\n        :param query: pandas query expression, e.g. Qty > 100 and Region == "North". Wrap column names containing spaces in backticks\n        :param limit: Rows to return (capped by the max_rows valve)\n        :param offset: Rows to skip, for paging\n        :param header_row: 0-indexed row holding the column headers\n        :return: JSON with total matched rows and the selected records\n        """\n        try:\n            filename, df = await self._prepared(\n                file_id, sheet, query, header_row, __files__, __user__\n            )\n        except Exception as e:\n            return json.dumps({"error": str(e)}, ensure_ascii=False)\n\n        if columns:\n            wanted = [c.strip() for c in columns.split(",") if c.strip()]\n            missing = [c for c in wanted if c not in df.columns]\n            if missing:\n                return json.dumps(\n                    {\n                        "error": f"unknown columns: {missing}",\n                        "available": list(df.columns),\n                    },\n                    ensure_ascii=False,\n                )\n            df = df[wanted]\n\n        total = int(len(df))\n        limit = max(1, min(int(limit), self.valves.max_rows))\n        offset = max(0, int(offset))\n        page = df.iloc[offset : offset + limit]\n\n        return json.dumps(\n            {\n                "filename": filename,\n                "total_rows": total,\n                "offset": offset,\n                "returned": int(len(page)),\n                "records": json.loads(\n                    page.to_json(orient="records", date_format="iso")\n                ),\n            },\n            ensure_ascii=False,\n        )\n\n    async def aggregate(\n        self,\n        file_id: str,\n        op: str,\n        column: Optional[str] = None,\n        sheet: Optional[str] = None,\n        group_by: Optional[str] = None,\n        query: Optional[str] = None,\n        header_row: int = 0,\n        __files__: Optional[list[dict]] = None,\n        __user__: Optional[dict] = None,\n    ) -> str:\n        """\n        Compute an aggregate over a spreadsheet column, optionally grouped. Prefer this\n        over reading rows and adding them up yourself — the result is exact and covers\n        every matching row, not just the ones returned.\n\n        :param file_id: File id from list_spreadsheets\n        :param op: One of sum, mean, median, min, max, count, nunique, std\n        :param column: Column to aggregate. Omit only when op is count\n        :param sheet: Sheet name. Defaults to the first sheet\n        :param group_by: Comma-separated columns to group by\n        :param query: pandas query expression applied before aggregating\n        :param header_row: 0-indexed row holding the column headers\n        :return: JSON with the aggregate result, or one row per group\n        """\n        op = str(op).strip().lower()\n        if op not in OPS:\n            return json.dumps(\n                {"error": f"op must be one of {list(OPS)}"}, ensure_ascii=False\n            )\n\n        try:\n            filename, df = await self._prepared(\n                file_id, sheet, query, header_row, __files__, __user__\n            )\n        except Exception as e:\n            return json.dumps({"error": str(e)}, ensure_ascii=False)\n\n        if column and column not in df.columns:\n            return json.dumps(\n                {"error": f"unknown column: {column}", "available": list(df.columns)},\n                ensure_ascii=False,\n            )\n\n        if (\n            op in NUMERIC_OPS\n            and column\n            and not pd.api.types.is_numeric_dtype(df[column])\n        ):\n            # sum on a text column would concatenate and hand the model a bogus total\n            return json.dumps(\n                {\n                    "error": f"column {column!r} is not numeric, so {op} is meaningless",\n                    "hint": "pick a numeric column, or use count/nunique/min/max",\n                },\n                ensure_ascii=False,\n            )\n\n        groups = [c.strip() for c in (group_by or "").split(",") if c.strip()]\n        missing = [c for c in groups if c not in df.columns]\n        if missing:\n            return json.dumps(\n                {\n                    "error": f"unknown group_by columns: {missing}",\n                    "available": list(df.columns),\n                },\n                ensure_ascii=False,\n            )\n\n        base = {\n            "filename": filename,\n            "op": op,\n            "column": column,\n            "matched_rows": int(len(df)),\n        }\n\n        try:\n            if not groups:\n                value = (\n                    len(df)\n                    if op == "count" and not column\n                    else getattr(df[column], op)()\n                )\n                base["result"] = (\n                    None\n                    if pd.isna(value)\n                    else value.item() if hasattr(value, "item") else value\n                )\n                return json.dumps(base, ensure_ascii=False, default=str)\n\n            target = df.groupby(groups, dropna=False)\n            series = (\n                target.size()\n                if op == "count" and not column\n                else getattr(target[column], op)()\n            )\n            result = series.reset_index(\n                name="value" if series.name is None else series.name\n            )\n            result = (\n                result.rename(columns={column: "value"})\n                if column in result.columns\n                else result\n            )\n        except Exception as e:\n            return json.dumps({**base, "error": str(e)}, ensure_ascii=False)\n\n        base["groups"] = int(len(result))\n        base["truncated"] = len(result) > self.valves.max_groups\n        base["results"] = json.loads(\n            result.head(self.valves.max_groups).to_json(\n                orient="records", date_format="iso"\n            )\n        )\n        return json.dumps(base, ensure_ascii=False, default=str)\n	[{"name": "aggregate", "description": "Compute an aggregate over a spreadsheet column, optionally grouped. Prefer this\\nover reading rows and adding them up yourself \\u2014 the result is exact and covers\\nevery matching row, not just the ones returned.", "parameters": {"properties": {"file_id": {"description": "File id from list_spreadsheets", "type": "string"}, "op": {"description": "One of sum, mean, median, min, max, count, nunique, std", "type": "string"}, "column": {"description": "Column to aggregate. Omit only when op is count", "type": "string"}, "sheet": {"description": "Sheet name. Defaults to the first sheet", "type": "string"}, "group_by": {"description": "Comma-separated columns to group by", "type": "string"}, "query": {"description": "pandas query expression applied before aggregating", "type": "string"}, "header_row": {"default": 0, "description": "0-indexed row holding the column headers", "type": "integer"}}, "required": ["file_id", "op"], "type": "object"}}, {"name": "list_spreadsheets", "description": "List the spreadsheets attached to this chat, with their sheet names, column\\nnames and row counts. Call this first to learn the file_id and the exact\\ncolumn spelling needed by read_sheet and aggregate.", "parameters": {"properties": {}, "type": "object"}}, {"name": "read_sheet", "description": "Read rows from a spreadsheet as records. Use it to inspect data, not to pull\\nthe whole file \\u2014 filter with query and narrow with columns instead.", "parameters": {"properties": {"file_id": {"description": "File id from list_spreadsheets", "type": "string"}, "sheet": {"description": "Sheet name. Defaults to the first sheet", "type": "string"}, "columns": {"description": "Comma-separated column names to return. Defaults to all", "type": "string"}, "query": {"description": "pandas query expression, e.g. Qty > 100 and Region == \\"North\\". Wrap column names containing spaces in backticks", "type": "string"}, "limit": {"default": 50, "description": "Rows to return (capped by the max_rows valve)", "type": "integer"}, "offset": {"default": 0, "description": "Rows to skip, for paging", "type": "integer"}, "header_row": {"default": 0, "description": "0-indexed row holding the column headers", "type": "integer"}}, "required": ["file_id"], "type": "object"}}]	{"description": "Read Excel", "manifest": {"title": "Excel Calc", "author": "Haadthip DIO", "version": "1.0", "required_open_webui_version": "0.5.0", "Authorization": "a file is readable only if it is attached to the current chat"}, "has_user_valves": false}	\N	1787048496	1787048496
procurement_price_search	490b4365-9153-406f-bd74-d898a971e18e	Procurement Price Search	"""\ntitle: Procurement Price Search\nauthor: Haadthip DIO\nversion: 3.2\nrequired_open_webui_version: 0.5.0\n\nSearch procurement prices from Azure AI Search index procurement-catalog-v1.\nOne document = one logical product with tiered pricing. Prices come from the\nExcel Master verbatim. Unit prices are never invented; calculate_total_price\nonly selects an awarded tier and multiplies its unit price by the quantity.\n\nCapabilities:\n- Hybrid search: BM25 keyword + vector (3072-dim), fused by Azure RRF\n- Thai word segmentation via th.microsoft analyzer\n- Semantic rerank on top (optional, queryType=semantic)\n- Filter: year, category, price range, quantity tier\n- Quantity tier matching: tiers/any OData filter\n- Category fallback: drops category filter if no results found\n\nCategory guide (send ONLY when user explicitly names the category):\n- POSM — สื่อ ณ จุดขาย (ร่มโค้ก, ถังน้ำแข็ง, กล่องทิชชู, PM Rack, Mega Rack, ป้าย)\n- Printing-MKT — งานพิมพ์การตลาด (โคมไฟ, PP Board, แบนเนอร์, ผ้าปูโต๊ะ, สติ๊กเกอร์, ธงราว)\n- Printing-Rate — งานพิมพ์ตามเรท (Arch, Wrap Around, โปสเตอร์, Tent card, Wobbler, ธงปีกนก, Sticker PVC, Coupon)\n- Garment — เสื้อผ้า (เสื้อยืด, เสื้อโปโล, เสื้อแจ็คเก็ต, สกรีน, ค่าปัก)\n- Premium — ของพรีเมียม (ร่ม, แก้วกระดาษ, ผ้าเบอร์วิ่ง, Menu Stand, เก้าอี้)\n\nQuantity filter warning: products have a minimum order quantity (MOQ).\nA quantity filter removes products whose MOQ exceeds the request. Search\nWITHOUT quantity first to identify the product, then check its tiers for\nthe user's requested quantity. If the quantity is below MOQ, report the\nMOQ and ask whether the user wants to adjust.\n\nAuthorization: Available to all users with access to the model.\n"""\n\nimport json\nimport os\nfrom typing import Literal, Optional\n\nfrom azure.core.credentials import AzureKeyCredential\nfrom azure.search.documents import SearchClient\nfrom azure.search.documents.models import VectorizedQuery\nfrom fastapi import Request\nfrom openai import OpenAI\nfrom pydantic import BaseModel, Field\n\n_SELECT_FIELDS = [\n    "logical_item_id",\n    "year",\n    "category",\n    "product_name",\n    "product_aliases",\n    "product_type",\n    "product_spec_text",\n    "product_condition_text",\n    "pricing_basis",\n    "notes_text",\n    "award_vendors",\n    "price_min",\n    "price_max",\n    "quantity_min_all",\n    "quantity_max_all",\n    "tiers",\n]\n\n\nclass Tools:\n    class Valves(BaseModel):\n        AZURE_SEARCH_ENDPOINT: str = Field(\n            default="https://srch-entchat-poc-sand.search.windows.net",\n            description="Azure AI Search endpoint"\n        )\n        AZURE_SEARCH_KEY: str = Field(\n            default="",\n            description="Azure AI Search admin key"\n        )\n        AZURE_SEARCH_INDEX: str = Field(\n            default="procurement-catalog-v1",\n            description="Search index name"\n        )\n        AZURE_SEARCH_SEMANTIC_CONFIG: str = Field(\n            default="procurement-semantic",\n            description="Semantic configuration name (for semantic mode)"\n        )\n        AZURE_OPENAI_ENDPOINT: str = Field(\n            default="https://app-litellm-poc-sand.azurewebsites.net",\n            description="OpenAI-compatible endpoint for embeddings (LiteLLM proxy base URL, no /v1 suffix)"\n        )\n        AZURE_OPENAI_KEY: str = Field(\n            default="",\n            description="Azure OpenAI API key"\n        )\n        AZURE_OPENAI_EMBEDDING_DEPLOYMENT: str = Field(\n            default="deploy-embedding-3-large",\n            description="Embedding model deployment name"\n        )\n        AZURE_OPENAI_API_VERSION: str = Field(\n            default="2024-10-21",\n            description="Azure OpenAI API version"\n        )\n        AZURE_SEARCH_API_VERSION: str = Field(\n            default="2024-07-01",\n            description="Azure AI Search API version"\n        )\n        max_results: int = Field(\n            default=5,\n            description="Maximum number of search results to return (capped at 5 per round)"\n        )\n        max_search_rounds: int = Field(\n            default=3,\n            description="Maximum search rounds per invocation (exact + wildcard retry)"\n        )\n\n    def __init__(self):\n        self.valves = self.Valves()\n        v = self.valves\n        # Valves are the admin-set source of truth (they survive the OWUI tool\n        # sandbox, where App Service Key Vault references are not resolvable).\n        # Env vars are only a fallback for fresh deploys with empty valves.\n        if not v.AZURE_SEARCH_ENDPOINT:\n            v.AZURE_SEARCH_ENDPOINT = os.getenv("AZURE_SEARCH_ENDPOINT", v.AZURE_SEARCH_ENDPOINT)\n        if not v.AZURE_SEARCH_KEY:\n            v.AZURE_SEARCH_KEY = os.getenv("AZURE_SEARCH_ADMIN_KEY", "")\n        if not v.AZURE_OPENAI_ENDPOINT:\n            base = os.getenv("OPENAI_API_BASE_URL", "").rstrip("/")\n            v.AZURE_OPENAI_ENDPOINT = base[:-3] if base.endswith("/v1") else base\n        if not v.AZURE_OPENAI_KEY:\n            v.AZURE_OPENAI_KEY = os.getenv("OPENAI_API_KEY", "")\n\n    def _get_embedding(self, text: str) -> list[float]:\n        """Generate embedding vector for text using an OpenAI-compatible endpoint.\n\n        The LiteLLM proxy exposes /v1/embeddings (OpenAI style) rather than\n        Azure's /openai/deployments/... path, so we use the OpenAI client with\n        base_url=<endpoint>/v1.\n        """\n        client = OpenAI(\n            api_key=self.valves.AZURE_OPENAI_KEY,\n            base_url=self.valves.AZURE_OPENAI_ENDPOINT.rstrip("/") + "/v1",\n        )\n        response = client.embeddings.create(\n            input=text,\n            model=self.valves.AZURE_OPENAI_EMBEDDING_DEPLOYMENT,\n        )\n        return response.data[0].embedding\n\n    def _build_filter(\n        self,\n        category: Optional[str] = None,\n        year: Optional[int] = None,\n        min_price: Optional[float] = None,\n        max_price: Optional[float] = None,\n        quantity: Optional[int] = None,\n    ) -> Optional[str]:\n        """Build OData filter string against the product-level schema."""\n        filters = []\n\n        if category:\n            filters.append(f"category eq '{category}'")\n        if year:\n            filters.append(f"year eq {year}")\n        if min_price is not None:\n            filters.append(f"price_min ge {min_price}")\n        if max_price is not None:\n            filters.append(f"price_max le {max_price}")\n        if quantity is not None:\n            # deterministic tier matching: a tier that can serve the quantity\n            filters.append(\n                f"tiers/any(t: t/quantity_min le {quantity} and "\n                f"(t/quantity_max ge {quantity} or t/quantity_max eq null))"\n            )\n\n        return " and ".join(filters) if filters else None\n\n    def _format_result(self, result: dict) -> dict:\n        """Flatten a product document into a readable result.\n\n        Tiers carry quantity + awarded_price. Values are returned verbatim\n        from the index; nothing is computed. award_vendors (ผู้ผ่านการประมูล)\n        comes from the รายชื่อผู้ผ่านการประมูล column.\n        """\n        tiers = []\n        for tier in result.get("tiers") or []:\n            tiers.append(\n                {\n                    "lead_time": tier.get("lead_time"),\n                    "quantity_label": tier.get("quantity_label"),\n                    "quantity_min": tier.get("quantity_min"),\n                    "quantity_max": tier.get("quantity_max"),\n                    "awarded_price": tier.get("awarded_price"),\n                }\n            )\n\n        return {\n            "logical_item_id": result.get("logical_item_id"),\n            "year": result.get("year"),\n            "category": result.get("category"),\n            "product_name": result.get("product_name"),\n            "product_aliases": result.get("product_aliases") or [],\n            "product_type": result.get("product_type"),\n            "pricing_basis": result.get("pricing_basis"),\n            "product_spec_text": result.get("product_spec_text"),\n            "product_condition_text": result.get("product_condition_text"),\n            "notes_text": result.get("notes_text"),\n            "award_vendors": result.get("award_vendors") or [],\n            "price_min": result.get("price_min"),\n            "price_max": result.get("price_max"),\n            "quantity_min_all": result.get("quantity_min_all"),\n            "quantity_max_all": result.get("quantity_max_all"),\n            "tiers": tiers,\n            "score": result.get("@search.score"),\n        }\n\n    def _search(\n        self,\n        search_text: str,\n        query_vector: list[float],\n        filter_expr: Optional[str],\n        use_semantic: bool,\n    ) -> list[dict]:\n        """Run HYBRID search: BM25 full-text (search_text) + vector (query_vector).\n\n        Azure AI Search fuses the two result sets (RRF) into a single ranked\n        list. `search_mode="any"` keeps the full-text side permissive so Thai\n        keyword hits and vector matches both contribute. Semantic reranking\n        (when enabled) is applied ON TOP of the hybrid results.\n        """\n        client = SearchClient(\n            endpoint=self.valves.AZURE_SEARCH_ENDPOINT,\n            index_name=self.valves.AZURE_SEARCH_INDEX,\n            credential=AzureKeyCredential(self.valves.AZURE_SEARCH_KEY),\n            api_version=self.valves.AZURE_SEARCH_API_VERSION,\n        )\n        vector_query = VectorizedQuery(\n            vector=query_vector,\n            k_nearest_neighbors=50,\n            fields="content_vector",\n        )\n        kwargs = {\n            "search_text": search_text,\n            "search_mode": "any",  # hybrid: BM25 + vector fused\n            "vector_queries": [vector_query],\n            "filter": filter_expr,\n            "top": max(1, min(self.valves.max_results, 5)),  # cap: 5 items per round\n            "select": _SELECT_FIELDS,\n        }\n        if use_semantic:\n            kwargs["query_type"] = "semantic"\n            kwargs["semantic_configuration_name"] = self.valves.AZURE_SEARCH_SEMANTIC_CONFIG\n        return list(client.search(**kwargs))\n\n    async def search_procurement_prices(\n        self,\n        query: str,\n        category: Optional[Literal["POSM", "Printing-MKT", "Printing-Rate", "Garment", "Premium"]] = None,\n        year: Optional[int] = None,\n        min_price: Optional[float] = None,\n        max_price: Optional[float] = None,\n        quantity: Optional[int] = None,\n        use_semantic: bool = False,\n        sort_by_price: bool = False,\n        use_wildcard: bool = False,\n        __user__: dict = None,\n        __request__: Request = None,\n        __event_emitter__=None,\n    ) -> str:\n        """\n        Search procurement products. Hybrid retrieval: keyword + vector.\n\n        Send quantity ONLY after identifying the product. Quantity filter\n        removes products whose minimum order quantity exceeds the request.\n        If you send quantity on the first search and get zero results,\n        retry without quantity first to find the product, then check its\n        tiers.\n\n        Args:\n            query: Search terms in Thai or English. Be specific. Include\n                  size, color, material when available (e.g. "ร่มโค้ก 40 นิ้ว\n                  โครงไฟเบอร์" not just "ร่ม").\n            category: Send ONLY when user states the category explicitly.\n                      Do NOT guess. Wrong category kills results.\n            year: Filter by year. Default: search all years.\n            min_price: Minimum awarded price.\n            max_price: Maximum awarded price.\n            quantity: DO NOT send on the first search. Send only after you\n                      have identified the product and want to match a tier.\n            use_semantic: True for fuzzy or paraphrased queries.\n            sort_by_price: True to sort cheapest first.\n            use_wildcard: True for partial Thai word matches.\n\n        Returns:\n            JSON with results array, each containing logical_item_id,\n            product_name, category, price_min/max, quantity_min_all/max_all,\n            tiers[], award_vendors, product_spec_text, pricing_basis.\n        """\n        if __event_emitter__:\n            await __event_emitter__(\n                {\n                    "type": "status",\n                    "data": {"description": f"กำลังค้นหา: {query}", "done": False},\n                }\n            )\n\n        try:\n            query_vector = self._get_embedding(query)\n            filter_expr = self._build_filter(\n                category=category,\n                year=year,\n                min_price=min_price,\n                max_price=max_price,\n                quantity=quantity,\n            )\n\n            search_text = query if not use_wildcard else (\n                f"{query}*" if not query.endswith("*") else query\n            )\n            # Search with at most max_search_rounds rounds: first exact, then\n            # wildcard, then (optionally) the query without a trailing star.\n            max_rounds = max(1, min(self.valves.max_search_rounds, 3))\n            candidates = [search_text]\n            if not use_wildcard and not query.endswith("*"):\n                candidates.append(f"{query}*")\n            if query.endswith("*"):\n                candidates.append(query[:-1])\n            candidates = list(dict.fromkeys(candidates))[:max_rounds]\n\n            results_list: list[dict] = []\n            for attempt in candidates:\n                results_list = self._search(\n                    search_text=attempt,\n                    query_vector=query_vector,\n                    filter_expr=filter_expr,\n                    use_semantic=use_semantic,\n                )\n                if len(results_list) > 0:\n                    break\n\n            # Category fallback: if the caller guessed a category and nothing\n            # matched, retry WITHOUT the category filter (the guess may be wrong).\n            category_dropped = False\n            if len(results_list) == 0 and filter_expr and category:\n                no_cat_filter = self._build_filter(\n                    category=None,\n                    year=year,\n                    min_price=min_price,\n                    max_price=max_price,\n                    quantity=quantity,\n                )\n                for attempt in candidates:\n                    results_list = self._search(\n                        search_text=attempt,\n                        query_vector=query_vector,\n                        filter_expr=no_cat_filter,\n                        use_semantic=use_semantic,\n                    )\n                    if len(results_list) > 0:\n                        category_dropped = True\n                        break\n\n            # Quantity fallback: if quantity filter killed all results, retry\n            # WITHOUT it. The product's MOQ may exceed the request. Return both\n            # the full product list and a flag so the LLM can report the MOQ.\n            quantity_dropped = False\n            if len(results_list) == 0 and filter_expr and quantity is not None:\n                no_qty_filter = self._build_filter(\n                    category=category,\n                    year=year,\n                    min_price=min_price,\n                    max_price=max_price,\n                    quantity=None,\n                )\n                for attempt in candidates:\n                    results_list = self._search(\n                        search_text=attempt,\n                        query_vector=query_vector,\n                        filter_expr=no_qty_filter,\n                        use_semantic=use_semantic,\n                    )\n                    if len(results_list) > 0:\n                        quantity_dropped = True\n                        break\n\n            if sort_by_price and results_list:\n                results_list.sort(key=lambda r: r.get("price_min") if r.get("price_min") is not None else float("inf"))\n\n            items = [self._format_result(r) for r in results_list]\n\n            if __event_emitter__:\n                await __event_emitter__(\n                    {\n                        "type": "status",\n                        "data": {"description": f"พบ {len(items)} รายการ", "done": True},\n                    }\n                )\n\n            if items:\n                response = {\n                    "success": True,\n                    "query": query,\n                    "total_results": len(items),\n                    "results": items,\n                }\n                if category_dropped:\n                    response["warning"] = (\n                        f"ไม่พบผลเมื่อ filter category='{category}' → "\n                        "ค้นใหม่โดยไม่ระบุ category (อาจเดาหมวดผิด) และได้ผลลัพธ์นี้"\n                    )\n                if quantity_dropped:\n                    response["warning"] = (\n                        f"ไม่พบผลเมื่อ filter quantity={quantity} → "\n                        "ค้นใหม่โดยไม่ระบุจำนวน (MOQ อาจสูงกว่าที่ขอ) "\n                        "ตรวจสอบ quantity_min_all ในผลลัพธ์และแจ้งผู้ใช้"\n                    )\n                return json.dumps(response, ensure_ascii=False, indent=2)\n            return json.dumps(\n                {\n                    "success": True,\n                    "query": query,\n                    "total_results": 0,\n                    "message": "ไม่พบสินค้าที่ตรงกับเงื่อนไข",\n                },\n                ensure_ascii=False,\n                indent=2,\n            )\n\n        except Exception as e:\n            error_msg = f"Search error: {str(e)}"\n            if __event_emitter__:\n                await __event_emitter__(\n                    {\n                        "type": "status",\n                        "data": {"description": error_msg, "done": True},\n                    }\n                )\n            return json.dumps({"success": False, "error": error_msg}, ensure_ascii=False)\n\n    async def get_cheapest_option(\n        self,\n        query: str,\n        category: Optional[Literal["POSM", "Printing-MKT", "Printing-Rate", "Garment", "Premium"]] = None,\n        year: Optional[int] = None,\n        __user__: dict = None,\n        __request__: Request = None,\n        __event_emitter__=None,\n    ) -> str:\n        """\n        Find the cheapest awarded option for a product.\n\n        Args:\n            query: Product search query\n            category: Filter by category\n            year: Filter by year\n\n        Returns:\n            JSON string with cheapest option details (from price_min, no computation)\n        """\n        return await self.search_procurement_prices(\n            query=query,\n            category=category,\n            year=year,\n            sort_by_price=True,\n            __user__=__user__,\n            __request__=__request__,\n            __event_emitter__=__event_emitter__,\n        )\n\n    async def calculate_total_price(\n        self,\n        quantity: int,\n        tiers: list,\n        __user__: dict = None,\n        __event_emitter__=None,\n    ) -> str:\n        """\n        Compute the total awarded price for a quantity from a product's tiers.\n        Deterministic tier matching — never invents prices.\n\n        Args:\n            quantity: Number of units the user wants.\n            tiers: The `tiers` array copied verbatim from the search result\n                   of the chosen product (quantity_min, quantity_max,\n                   awarded_price, quantity_label).\n\n        Returns:\n            JSON with matched tier, unit_price, total_price = unit x quantity,\n            or below_moq info (MOQ + total at MOQ) when quantity is under\n            the minimum tier.\n        """\n        valid = [\n            t for t in (tiers or [])\n            if t.get("awarded_price") is not None and t.get("quantity_min") is not None\n        ]\n        if not valid:\n            return json.dumps({"success": False, "error": "ไม่มี tier ที่ใช้ได้ (missing awarded_price/quantity_min)"}, ensure_ascii=False)\n        valid.sort(key=lambda t: t["quantity_min"])\n\n        matched = None\n        for t in valid:\n            qmin = t["quantity_min"]\n            qmax = t.get("quantity_max")\n            if quantity < qmin:\n                break  # below MOQ — no tier covers this quantity\n            if qmax is None or quantity <= qmax:\n                matched = t\n                break\n        if matched is None and quantity < valid[0]["quantity_min"]:\n            lowest = valid[0]\n            moq = lowest["quantity_min"]\n            unit = lowest["awarded_price"]\n            return json.dumps({\n                "success": True,\n                "quantity": quantity,\n                "below_moq": True,\n                "moq": moq,\n                "unit_price_at_moq": unit,\n                "total_at_moq": round(unit * moq, 2),\n                "message": f"จำนวน {quantity} ต่ำกว่าขั้นต่ำ {moq} — ไม่มีเรทที่ตรง; ทางเลือก: สั่งตาม MOQ {moq} ชิ้น (รวม {unit * moq:,.2f} บาท) หรือปรึกษาจัดซื้อ",\n            }, ensure_ascii=False, indent=2)\n        if matched is None:\n            return json.dumps({\n                "success": False,\n                "reason": "no_matching_tier",\n                "quantity": quantity,\n                "error": "ไม่มี awarded tier ที่ครอบคลุมจำนวนนี้ — ห้าม extrapolate ราคา",\n            }, ensure_ascii=False, indent=2)\n\n        unit = matched["awarded_price"]\n        total = round(unit * quantity, 2)\n        return json.dumps({\n            "success": True,\n            "quantity": quantity,\n            "matched_tier": {\n                "quantity_label": matched.get("quantity_label"),\n                "quantity_min": matched["quantity_min"],\n                "quantity_max": matched.get("quantity_max"),\n            },\n            "unit_price": unit,\n            "total_price": total,\n            "formula": f"{unit} x {quantity} = {total}",\n        }, ensure_ascii=False, indent=2)\n\n    async def compare_vendors(\n        self,\n        query: str,\n        category: Optional[Literal["POSM", "Printing-MKT", "Printing-Rate", "Garment", "Premium"]] = None,\n        year: Optional[int] = None,\n        quantity: Optional[int] = None,\n        __user__: dict = None,\n        __request__: Request = None,\n        __event_emitter__=None,\n    ) -> str:\n        """\n        Compare awarded options for the same product.\n\n        Args:\n            query: Product search query\n            category: Filter by category\n            year: Filter by year\n            quantity: Required quantity to match a specific tier\n\n        Returns:\n            JSON string with awarded options per tier (price_min/max + award_vendors)\n        """\n        return await self.search_procurement_prices(\n            query=query,\n            category=category,\n            year=year,\n            quantity=quantity,\n            sort_by_price=True,\n            __user__=__user__,\n            __request__=__request__,\n            __event_emitter__=__event_emitter__,\n        )\n	[{"name": "compare_vendors", "description": "Compare awarded options for the same product.\\n\\nArgs:\\nquery: Product search query\\ncategory: Filter by category\\nyear: Filter by year\\nquantity: Required quantity to match a specific tier\\n\\nReturns:\\nJSON string with awarded options per tier (price_min/max + award_vendors)", "parameters": {"properties": {"query": {"type": "string"}, "category": {"enum": ["POSM", "Printing-MKT", "Printing-Rate", "Garment", "Premium"], "type": "string"}, "year": {"type": "integer"}, "quantity": {"type": "integer"}}, "required": ["query"], "type": "object"}}, {"name": "get_cheapest_option", "description": "Find the cheapest awarded option for a product.\\n\\nArgs:\\nquery: Product search query\\ncategory: Filter by category\\nyear: Filter by year\\n\\nReturns:\\nJSON string with cheapest option details (from price_min, no computation)", "parameters": {"properties": {"query": {"type": "string"}, "category": {"enum": ["POSM", "Printing-MKT", "Printing-Rate", "Garment", "Premium"], "type": "string"}, "year": {"type": "integer"}}, "required": ["query"], "type": "object"}}, {"name": "search_procurement_prices", "description": "Search procurement products. Hybrid retrieval: keyword + vector.\\n\\nSend quantity ONLY after identifying the product. Quantity filter\\nremoves products whose minimum order quantity exceeds the request.\\nIf you send quantity on the first search and get zero results,\\nretry without quantity first to find the product, then check its\\ntiers.\\n\\nArgs:\\nquery: Search terms in Thai or English. Be specific. Include\\nsize, color, material when available (e.g. \\"\\u0e23\\u0e48\\u0e21\\u0e42\\u0e04\\u0e49\\u0e01 40 \\u0e19\\u0e34\\u0e49\\u0e27\\n\\u0e42\\u0e04\\u0e23\\u0e07\\u0e44\\u0e1f\\u0e40\\u0e1a\\u0e2d\\u0e23\\u0e4c\\" not just \\"\\u0e23\\u0e48\\u0e21\\").\\ncategory: Send ONLY when user states the category explicitly.\\nDo NOT guess. Wrong category kills results.\\nyear: Filter by year. Default: search all years.\\nmin_price: Minimum awarded price.\\nmax_price: Maximum awarded price.\\nquantity: DO NOT send on the first search. Send only after you\\nhave identified the product and want to match a tier.\\nuse_semantic: True for fuzzy or paraphrased queries.\\nsort_by_price: True to sort cheapest first.\\nuse_wildcard: True for partial Thai word matches.\\n\\nReturns:\\nJSON with results array, each containing logical_item_id,\\nproduct_name, category, price_min/max, quantity_min_all/max_all,\\ntiers[], award_vendors, product_spec_text, pricing_basis.", "parameters": {"properties": {"query": {"type": "string"}, "category": {"enum": ["POSM", "Printing-MKT", "Printing-Rate", "Garment", "Premium"], "type": "string"}, "year": {"type": "integer"}, "min_price": {"type": "number"}, "max_price": {"type": "number"}, "quantity": {"type": "integer"}, "use_semantic": {"default": false, "type": "boolean"}, "sort_by_price": {"default": false, "type": "boolean"}, "use_wildcard": {"default": false, "type": "boolean"}}, "required": ["query"], "type": "object"}}]	{"description": "Search awarded procurement prices from Azure AI Search (hybrid: BM25 + vector)", "manifest": {"title": "Procurement Price Search", "author": "Haadthip DIO", "version": "3.1", "required_open_webui_version": "0.5.0", "Capabilities": "", "Authorization": "Available to all users with access to the model."}, "has_user_valves": false}	{"AZURE_SEARCH_ENDPOINT": "https://srch-entchat-qas.search.windows.net", "AZURE_SEARCH_KEY": "tLfXnXbmMSuchgSckUs2apeqOMevZWpwI4vGUISRVIAzSeAQhlVK", "AZURE_SEARCH_INDEX": "procurement-catalog-v1", "AZURE_SEARCH_SEMANTIC_CONFIG": "procurement-semantic", "AZURE_OPENAI_ENDPOINT": "https://app-litellm-qas.azurewebsites.net", "AZURE_OPENAI_KEY": "sk-XsIT5NBvNr3Ir6FUKa-pag", "AZURE_OPENAI_EMBEDDING_DEPLOYMENT": "deploy-embedding-3-large", "AZURE_OPENAI_API_VERSION": "2024-10-21", "AZURE_SEARCH_API_VERSION": "2024-07-01", "max_results": 5, "max_search_rounds": 3}	1788768509	1787048495
fabric_data_warehouse_query_tool	490b4365-9153-406f-bd74-d898a971e18e	Fabric Data Warehouse Query Tool	"""\ntitle: Fabric Data Warehouse Query Tool\nauthor: Haadthip DIO\nversion: 1.5\nrequired_open_webui_version: 0.5.0\n\nQuery Microsoft Fabric Data Warehouse (LH_OTC_TEST) using Entra ID auth.\nDomain helpers: Sales/OTC, Targets, Customers, Products, Credit, Coolers, Visits, RFM Segmentation.\nCustom T-SQL (SELECT/WITH only), schema inspection, pagination (hard cap: 20).\n"""\n\nimport asyncio\nimport json\nimport os\nimport re\nimport struct\nfrom typing import Optional\nfrom pydantic import BaseModel, Field\n\nimport pyodbc\nfrom azure.identity import (\n    DefaultAzureCredential,\n    ClientSecretCredential,\n)\n\n\nclass Tools:\n    HARD_MAX_LIMIT = 20\n    WILDCARD_SELECT_RE = re.compile(\n        r"(?:\\bSELECT\\b|,)\\s*"\n        r"(?:DISTINCT\\s+)?(?:TOP\\s+\\d+\\s+)?"\n        r"(?:[A-Za-z_]\\w*[.])?\\s*\\*"\n        r"(?=\\s*(?:,|\\bFROM\\b|$))",\n        re.IGNORECASE,\n    )\n\n    class Valves(BaseModel):\n        FABRIC_ENDPOINT: str = Field(\n            default="ypmukualhmkuhbmumqiyxplusu-ytem5s6jyj6e5cg2lqqkuiiufq.datawarehouse.fabric.microsoft.com",\n            description="Fabric Data Warehouse Endpoint server hostname"\n        )\n        DEFAULT_DATABASE: str = Field(\n            default="LH_OTC_TEST",\n            description="Default Database / Lakehouse / Warehouse name to query"\n        )\n        ODBC_DRIVER: str = Field(\n            default="ODBC Driver 18 for SQL Server",\n            description="Installed ODBC Driver name"\n        )\n        AZURE_TENANT_ID: str = Field(\n            default="",\n            description="(Optional) Microsoft Entra Tenant ID for Service Principal auth"\n        )\n        AZURE_CLIENT_ID: str = Field(\n            default="",\n            description="(Optional) Microsoft Entra Client ID for Service Principal auth"\n        )\n        AZURE_CLIENT_SECRET: str = Field(\n            default="",\n            description="(Optional) Microsoft Entra Client Secret for Service Principal auth"\n        )\n        ACCESS_TOKEN: str = Field(\n            default="",\n            description="(Optional) Pre-acquired Entra ID bearer token"\n        )\n        DEFAULT_LIMIT: int = Field(\n            default=20,\n            description="Default maximum number of rows to return per query page (hard cap: 20)"\n        )\n        MAX_LIMIT_CAP: int = Field(\n            default=20,\n            description="Maximum rows per request; the tool hard-caps this value at 20"\n        )\n        CONNECT_TIMEOUT: int = Field(\n            default=15,\n            description="Connection timeout in seconds"\n        )\n\n    def __init__(self):\n        self.valves = self.Valves()\n        if os.getenv("FABRIC_ENDPOINT"):\n            self.valves.FABRIC_ENDPOINT = os.getenv("FABRIC_ENDPOINT")\n        if not self.valves.AZURE_TENANT_ID:\n            self.valves.AZURE_TENANT_ID = os.getenv("MICROSOFT_CLIENT_TENANT_ID", "")\n        if not self.valves.AZURE_CLIENT_ID:\n            self.valves.AZURE_CLIENT_ID = os.getenv("MICROSOFT_CLIENT_ID", "")\n        if not self.valves.AZURE_CLIENT_SECRET:\n            self.valves.AZURE_CLIENT_SECRET = os.getenv("MICROSOFT_CLIENT_SECRET", "")\n\n    @classmethod\n    def _validate_read_only_query(cls, query: str) -> Optional[str]:\n        if not query:\n            return "Error: SQL query cannot be empty."\n\n        upper_query = query.upper()\n        if not upper_query.startswith(("SELECT", "WITH")):\n            return "Error: Only read-only queries (SELECT or WITH) are allowed."\n\n        if re.search(\n            r"\\b(?:INSERT|UPDATE|DELETE|MERGE|DROP|ALTER|CREATE|TRUNCATE|GRANT|DENY|EXEC|EXECUTE)\\b",\n            query,\n            re.IGNORECASE,\n        ):\n            return "Error: Data-modifying and procedure statements are not allowed."\n\n        if cls.WILDCARD_SELECT_RE.search(query):\n            return (\n                "Error: SELECT * is not allowed. "\n                "Select only the columns required to answer the question."\n            )\n\n        return None\n\n    def _normalise_limit(self, requested_limit: Optional[int]) -> int:\n        try:\n            default_limit = int(self.valves.DEFAULT_LIMIT)\n        except (TypeError, ValueError):\n            default_limit = self.HARD_MAX_LIMIT\n\n        try:\n            configured_cap = int(self.valves.MAX_LIMIT_CAP)\n        except (TypeError, ValueError):\n            configured_cap = self.HARD_MAX_LIMIT\n\n        try:\n            row_limit = int(requested_limit) if requested_limit is not None else default_limit\n        except (TypeError, ValueError):\n            row_limit = default_limit\n\n        if row_limit <= 0:\n            row_limit = default_limit\n        if row_limit <= 0:\n            row_limit = self.HARD_MAX_LIMIT\n\n        if configured_cap <= 0:\n            configured_cap = self.HARD_MAX_LIMIT\n\n        return max(1, min(row_limit, configured_cap, self.HARD_MAX_LIMIT))\n\n    def _resolve_database_name(self, database_name: Optional[str]) -> str:\n        """Resolve the only Fabric warehouse supported by this tool."""\n        candidate = (database_name or "").strip()\n        if candidate.lower() in {"", "?", "none", "null", "undefined"}:\n            return self.valves.DEFAULT_DATABASE\n        if candidate.casefold() != self.valves.DEFAULT_DATABASE.casefold():\n            raise ValueError(\n                f"Unsupported Fabric database `{candidate}`. This tool is configured for "\n                f"`{self.valves.DEFAULT_DATABASE}` only; `gold` and `dv` are schemas, "\n                "not database names. Omit database_name and qualify tables as "\n                "`gold.<table>` or `dv.<table>`."\n            )\n        return self.valves.DEFAULT_DATABASE\n\n    @staticmethod\n    def _sql_literal(value: object) -> str:\n        """Quote a user-supplied string for a read-only SQL filter."""\n        return "'" + str(value).replace("'", "''") + "'"\n\n    def _sync_get_connection_and_query(\n        self, database_name: str, cleaned_query: str, limit: int, offset: int\n    ) -> str:\n        db = self._resolve_database_name(database_name)\n        endpoint = self.valves.FABRIC_ENDPOINT\n\n        token_str = self.valves.ACCESS_TOKEN.strip()\n        if not token_str and self.valves.AZURE_CLIENT_ID and self.valves.AZURE_CLIENT_SECRET and self.valves.AZURE_TENANT_ID:\n            try:\n                cred = ClientSecretCredential(\n                    tenant_id=self.valves.AZURE_TENANT_ID,\n                    client_id=self.valves.AZURE_CLIENT_ID,\n                    client_secret=self.valves.AZURE_CLIENT_SECRET,\n                )\n                token_obj = cred.get_token("https://database.windows.net/.default")\n                token_str = token_obj.token\n            except Exception:\n                token_str = ""\n\n        # Priority 3: DefaultAzureCredential fallback\n        if not token_str:\n            try:\n                credential = DefaultAzureCredential()\n                token_obj = credential.get_token("https://database.windows.net/.default")\n                token_str = token_obj.token\n            except Exception as e:\n                raise RuntimeError(\n                    f"No ACCESS_TOKEN provided and Azure credentials failed: {str(e)}. "\n                    "Please paste a valid Entra ID Access Token into Tool Valves."\n                )\n\n        if not token_str:\n            raise RuntimeError("Failed to acquire Entra ID Access Token for Fabric connection.")\n\n        token_bytes = token_str.encode("utf-16-le")\n        token_struct = struct.pack(f"<I{len(token_bytes)}s", len(token_bytes), token_bytes)\n        SQL_COPT_SS_ACCESS_TOKEN = 1256\n\n        conn_str = (\n            f"Driver={{{self.valves.ODBC_DRIVER}}};"\n            f"Server={endpoint},1433;"\n            f"Database={db};"\n            "Encrypt=yes;"\n            "TrustServerCertificate=no;"\n        )\n\n        conn = None\n        try:\n            conn = pyodbc.connect(\n                conn_str,\n                attrs_before={SQL_COPT_SS_ACCESS_TOKEN: token_struct},\n                timeout=self.valves.CONNECT_TIMEOUT\n            )\n            cursor = conn.cursor()\n            cursor.execute(cleaned_query)\n\n            if not cursor.description:\n                return "Query executed successfully with no output."\n\n            columns = [column[0] for column in cursor.description]\n\n            remaining_offset = max(offset, 0)\n            while remaining_offset > 0:\n                skipped_rows = cursor.fetchmany(min(remaining_offset, self.HARD_MAX_LIMIT))\n                if not skipped_rows:\n                    break\n                remaining_offset -= len(skipped_rows)\n\n            rows = cursor.fetchmany(limit)\n        finally:\n            if conn is not None:\n                conn.close()\n\n        if not rows:\n            return f"No results found in database `{db}` (Page Offset: {offset}, Limit: {limit})."\n\n        results = []\n        for row in rows:\n            row_dict = {}\n            for idx, col in enumerate(columns):\n                val = row[idx]\n                row_dict[col] = str(val) if val is not None else None\n            results.append(row_dict)\n\n        page_num = (offset // limit) + 1\n        summary = (\n            f"Database: `{db}` | Page: {page_num} (Offset: {offset}, Limit: {limit}) | "\n            f"Returned {len(results)} rows:\\n\\n"\n            "```json\\n" + json.dumps(results, ensure_ascii=False, indent=2) + "\\n```"\n        )\n        return summary\n\n    async def query_fabric(\n        self,\n        sql_query: str,\n        database_name: Optional[str] = None,\n        limit: Optional[int] = None,\n        offset: Optional[int] = 0,\n        page: Optional[int] = None,\n        __user__: Optional[dict] = None\n    ) -> str:\n        """\n        Execute T-SQL SELECT/WITH query. Must list explicit columns (no SELECT *).\n        :param sql_query: T-SQL with explicit columns, e.g. 'SELECT TOP 20 BillingDate, SumBillNetRevenue FROM dv.mlv_sale_preformance_aggregate'\n        :param limit: Max rows (hard cap: 20)\n        :param page: Page number (1-indexed, overrides offset)\n        """\n        cleaned_query = sql_query.strip()\n\n        validation_error = self._validate_read_only_query(cleaned_query)\n        if validation_error:\n            return validation_error\n\n        row_limit = self._normalise_limit(limit)\n\n        try:\n            target_db = self._resolve_database_name(database_name)\n        except ValueError as e:\n            return f"Error resolving Fabric database: {e}"\n\n        if page and page > 0:\n            row_offset = (page - 1) * row_limit\n        else:\n            row_offset = max(offset or 0, 0)\n\n        try:\n            loop = asyncio.get_running_loop()\n            result = await loop.run_in_executor(\n                None, self._sync_get_connection_and_query, target_db, cleaned_query, row_limit, row_offset\n            )\n            return result\n\n        except Exception as e:\n            return f"Error executing query on Fabric `{target_db}`: {str(e)}"\n\n    async def query_sales_performance(\n        self,\n        date_from: Optional[str] = None,\n        date_to: Optional[str] = None,\n        sub_org: Optional[str] = None,\n        zone: Optional[str] = None,\n        brand_key: Optional[str] = None,\n        customer_key: Optional[str] = None,\n        limit: Optional[int] = 20,\n        page: Optional[int] = 1,\n        __user__: Optional[dict] = None\n    ) -> str:\n        """\n        Query sales (Net Revenue, PC, UC) from dv.mlv_sale_preformance_aggregate.\n        Filter: date (YYYY-MM-DD), sub_org, zone, brand_key, customer_key. Limit: 20.\n        """\n        where_clauses = []\n        if date_from:\n            where_clauses.append(f"BillingDate >= {self._sql_literal(date_from)}")\n        if date_to:\n            where_clauses.append(f"BillingDate <= {self._sql_literal(date_to)}")\n        if sub_org:\n            where_clauses.append(f"SubOrgKey = {self._sql_literal(sub_org)}")\n        if zone:\n            where_clauses.append(f"Zone LIKE {self._sql_literal(f'%{zone}%')}")\n        if brand_key:\n            where_clauses.append(f"BrandKey = {self._sql_literal(brand_key)}")\n        if customer_key:\n            where_clauses.append(f"BillCustomerKey = {self._sql_literal(customer_key)}")\n\n        where_sql = f"WHERE {' AND '.join(where_clauses)}" if where_clauses else ""\n        query = f"""\n            SELECT BillingDate, SubOrgKey, Zone, BrandKey, PackSizeKey, BillCustomerKey,\n                   SumBillNetRevenue, SumBillPCVolume, SumBillUCVolume\n            FROM dv.mlv_sale_preformance_aggregate\n            {where_sql}\n            ORDER BY BillingDate DESC\n        """\n        return await self.query_fabric(\n            sql_query=query, limit=self._normalise_limit(limit), page=page, __user__=__user__\n        )\n\n    async def query_sales_targets(\n        self,\n        year: Optional[int] = None,\n        month: Optional[int] = None,\n        sub_org: Optional[str] = None,\n        material_no: Optional[str] = None,\n        customer_key: Optional[str] = None,\n        limit: Optional[int] = 20,\n        page: Optional[int] = 1,\n        __user__: Optional[dict] = None\n    ) -> str:\n        """\n        Query sales targets (Revenue, PC, UC) from dv.mlv_sale_target or dv.mlv_sale_target_customer.\n        Filter: year, month, sub_org, material_no, customer_key. Limit: 20.\n        """\n        if customer_key:\n            where_clauses = [f"CustomerKey = {self._sql_literal(customer_key)}"]\n            if year:\n                where_clauses.append(f"Year = {int(year)}")\n            if month:\n                where_clauses.append(f"MonthNumber = {int(month)}")\n         